diff --git a/tests/auth.test.js b/tests/auth.test.js
new file mode 100644
index 0000000..f928017
--- /dev/null
+++ b/tests/auth.test.js
@@ -0,0 +1,79 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { mkdtempSync, writeFileSync, rmSync } from "node:fs";
+import { tmpdir } from "node:os";
+import { join } from "node:path";
+import { createApp } from "../src/http/server.js";
+import { openStore } from "../src/db/store.js";
+import { NOW, fresh, seed } from "./helpers.js";
+
+const headers = (role) => ({ Authorization: `Bearer seed-${role}` });
+
+test("authentication rejects missing, malformed and unknown keys before routing", async () => {
+  const store = fresh();
+  const handle = createApp(store);
+  for (const authorization of [undefined, "Basic seed-manager", "Bearer unknown", "Bearer "]) {
+    const result = await handle({ path: "/nope", headers: { authorization } });
+    assert.equal(result.status, 401);
+    assert.equal(result.body.error.code, "unauthorized");
+    assert.equal(typeof result.body.error.message, "string");
+  }
+  assert.deepEqual(store.data.audit, []);
+});
+
+test("viewer reads but cannot write or read audit; cook cannot manage", async () => {
+  const store = fresh();
+  const handle = createApp(store);
+  assert.equal((await handle({ path: "/items", headers: headers("viewer") })).status, 200);
+  const before = structuredClone(store.data);
+  for (const role of ["viewer", "cook"]) {
+    for (const request of [{ path: "/audit" }, { method: "POST", path: "/stocktakes", body: { location: "dry" } }, { method: "PUT", path: "/items/1/allergens", body: { allergens: [] } }]) {
+      const result = await handle({ ...request, headers: headers(role) });
+      assert.equal(result.status, 403);
+      assert.equal(result.body.error.code, "forbidden");
+    }
+  }
+  assert.deepEqual(store.data, before);
+});
+
+test("cook can perform all four permitted writes and audit is newest first", async () => {
+  const store = fresh();
+  const handle = createApp(store, { clock: () => NOW });
+  const take = await handle({ method: "POST", path: "/stocktakes", headers: headers("manager"), body: { location: "dry" } });
+  for (const request of [
+    { path: "/recipes/1/cook", body: { portions: 1 } },
+    { path: "/batches/1/waste", body: { qty: 0.1 } },
+    { path: "/temperatures", body: { location: "fridge", celsius: 4 } },
+    { path: `/stocktakes/${take.body.id}/counts`, body: { batchId: 6, counted: 12 } },
+  ]) {
+    const result = await handle({ ...request, method: "POST", headers: headers("cook") });
+    assert.ok(result.status < 300, JSON.stringify(result));
+  }
+  const result = await handle({ path: "/audit", headers: headers("manager") });
+  assert.deepEqual(result.body, [...store.data.audit].reverse());
+  assert.deepEqual(result.body[0], { time: new Date(NOW).toISOString(), name: "Seed cook", method: "POST", path: `/stocktakes/${take.body.id}/counts`, status: 200 });
+  assert.equal(result.body.length, 5);
+  const failed = await handle({ method: "POST", path: "/recipes/1/cook", headers: headers("cook"), body: { portions: 100000 } });
+  assert.equal(failed.status, 409);
+  assert.equal(store.data.audit.length, 5);
+});
+
+test("data and audit persist together with exactly one save", async () => {
+  const dir = mkdtempSync(join(tmpdir(), "larder-audit-"));
+  try {
+    const file = join(dir, "db.json");
+    writeFileSync(file, JSON.stringify(seed()));
+    const store = openStore(file);
+    const save = store.save.bind(store);
+    let saves = 0;
+    store.save = () => { saves++; save(); };
+    const result = await createApp(store, { clock: () => NOW })({ method: "POST", path: "/temperatures", headers: headers("cook"), body: { location: "fridge", celsius: 4 } });
+    assert.equal(result.status, 201);
+    assert.equal(saves, 1);
+    const reopened = openStore(file);
+    assert.deepEqual(reopened.data.audit, store.data.audit);
+    assert.deepEqual(reopened.data.temperatures, store.data.temperatures);
+  } finally {
+    rmSync(dir, { recursive: true, force: true });
+  }
+});
